i=json.loads((O/'dmn-candidate-board-inventory.json').read_text());assert i['pcb_sha256']==hashlib.sha256(parent.read_bytes()).hexdigest();p=next(p for p in i['parts']if p['ref']=='TH1');assert p['side']=='B';x,y=p['position_mm'];y=-y
